---@field totalRunningInstanceCount? aws.ecs.BoxedInteger The total number of instances running daemon tasks for this revision.
---@field totalWithoutDaemonInstanceCount? aws.ecs.BoxedInteger The total number of instances running without the daemon task for this revision, across all capacity providers. These instances aren't included in totalRunningInstanceCount.
---@field totalDrainingInstanceCount? aws.ecs.BoxedInteger The total number of instances being drained for this revision during the deployment.

---@alias aws.ecs.DaemonDeploymentRevisionDetailList aws.ecs.DaemonDeploymentRevisionDetail[]

---@alias aws.ecs.DaemonDeploymentRollbackMonitorsStatus "TRIGGERED"|"MONITORING"|"MONITORING_COMPLETE"|"DISABLED"

---@alias aws.ecs.DaemonDeploymentStatus "PENDING"|"SUCCESSFUL"|"STOPPED"|"STOP_REQUESTED"|"IN_PROGRESS"|"ROLLBACK_IN_PROGRESS"|"ROLLBACK_SUCCESSFUL"|"ROLLBACK_FAILED"

---@alias aws.ecs.DaemonDeploymentStatusList (aws.ecs.DaemonDeploymentStatus|string)[]

