---@field status? aws.ecs.ServiceDeploymentRollbackMonitorsStatus The circuit breaker status. Amazon ECS is not using the circuit breaker for service deployment failures when the status is DISABLED.
---@field failureCount aws.ecs.Integer The number of times the circuit breaker detected a service deploymeny failure.
---@field threshold aws.ecs.Integer The threshhold which determines that the service deployment failed.

---@alias aws.ecs.ServiceDeploymentLifecycleStage "RECONCILE_SERVICE"|"PRE_SCALE_UP"|"SCALE_UP"|"POST_SCALE_UP"|"TEST_TRAFFIC_SHIFT"|"POST_TEST_TRAFFIC_SHIFT"|"PRODUCTION_TRAFFIC_SHIFT"|"POST_PRODUCTION_TRAFFIC_SHIFT"|"BAKE_TIME"|"CLEAN_UP"

---@alias aws.ecs.ServiceDeploymentRollbackMonitorsStatus "TRIGGERED"|"MONITORING"|"MONITORING_COMPLETE"|"DISABLED"

---@alias aws.ecs.ServiceDeploymentStatus "PENDING"|"SUCCESSFUL"|"STOPPED"|"STOP_REQUESTED"|"IN_PROGRESS"|"ROLLBACK_REQUESTED"|"ROLLBACK_IN_PROGRESS"|"ROLLBACK_SUCCESSFUL"|"ROLLBACK_FAILED"

---@alias aws.ecs.ServiceDeploymentStatusList (aws.ecs.ServiceDeploymentStatus|string)[]

---@alias aws.ecs.ServiceDeployments aws.ecs.ServiceDeployment[]

---@alias aws.ecs.ServiceDeploymentsBrief aws.ecs.ServiceDeploymentBrief[]

